import{_ as e,a as o,b as i,c as s,d as a,e as n,f as r,g as c}from"./chunks/en_m_nastaveni.CupdCm4p.js";import{_ as l}from"./chunks/m_btn_hamburger.CftTsS04.js";import{_ as h,o as p,c as g,aa as d}from"./chunks/framework.BAs_AphD.js";const T=JSON.parse('{"title":"Main App Menu","description":"","frontmatter":{"title":"Main App Menu","wiki":"en:diary:m_project_list"},"headers":[],"relativePath":"en/diary/m_project_list.md","filePath":"en/diary/m_project_list.md","lastUpdated":1794388980000}'),u={name:"en/diary/m_project_list.md"};function m(f,t,y,w,_,j){return p(),g("div",null,[...t[0]||(t[0]=[d('<h1 id="main-app-menu" tabindex="-1">Main App Menu <a class="header-anchor" href="#main-app-menu" aria-label="Permalink to &quot;Main App Menu&quot;">​</a></h1><figure class="shot" style="--w:280px;"><img src="'+e+'" alt="App navigation menu" width="250" loading="lazy"></figure><p>The app&#39;s navigation menu is accessible from almost anywhere using the hamburger menu <img src="'+l+'" alt="Hamburger menu - app navigation menu" width="20" data-no-zoom loading="lazy"> in the top-left corner. If a left-pointing arrow ← is displayed in the current location, follow it first. The required icon will then become visible.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The main menu is very similar to the navigation panel in the web version of the application, so navigating it should be simple and intuitive for users.</p><p>It is only important to keep in mind that the functionality of the mobile app is limited, particularly when it comes to configuration and settings.</p></div><p>In the upper third of the menu, over the project image, you will see the <strong>short project name</strong> and the name of its <strong>last viewed Project Diary</strong>. Below this information is the <strong>name of the logged-in account (email address)</strong>.</p><p>The active <strong>Project List</strong> and <strong>Settings</strong> icons link to the respective pages, which are described in more detail below.</p><p>In the <strong>Project Diary</strong> module, you can access the <strong>Diary List</strong> for the current project (allowing you to switch to another Project Diary), the <strong>Documents</strong> of the current diary, or the <strong>Daily Records</strong> of the current diary.</p><p>In the <strong>Ticket Management</strong> module, you can access the <strong>Ticket List</strong> for the current project.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For <strong>quick switching between the diary and tickets</strong> on the current project, use the <strong>icons in the header of the diary or ticket list</strong>:</p><p><img src="'+o+'" alt="Switching from tickets to the Project Diary of the selected project" width="250" loading="lazy"> <img src="'+i+'" alt="Switching from the Project Diary to tickets for the selected project" width="250" loading="lazy"></p></div><h2 id="project-list" tabindex="-1">Project List <a class="header-anchor" href="#project-list" aria-label="Permalink to &quot;Project List&quot;">​</a></h2><figure class="shot" style="--w:280px;"><img src="'+s+'" alt="Link to the Project List" width="250" loading="lazy"></figure><p>The <strong>Project List</strong> is undoubtedly the main navigation icon, allowing users to move freely from one project to another. Its placement in the main menu provides quick access.</p><figure class="shot" style="--w:280px;"><img src="'+a+'" alt="Project List" width="250" loading="lazy"></figure><figure class="shot" style="--w:280px;"><img src="'+n+'" alt="Project Details" width="250" loading="lazy"></figure><p>The list displays all projects the user has access to.</p><p>The <strong>Details</strong> icon expands to display <strong>basic project information</strong>.</p><p>The <strong>Diary</strong> icon takes the user <strong>to the Project Diary</strong> of the selected project, or to the Diary List if the project has multiple diaries.</p><p>The <strong>Tickets</strong> icon takes the user <strong>to the ticket list</strong> of the selected project.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A module that has not been activated for a project is displayed in the list with an inactive (grayed-out) icon.</p></div><p>The entire field containing the project image and name is also active ⇒ a project with a single diary opens directly to the diary&#39;s Daily Records for the current day, while a project with multiple diaries opens to the Diary List. If only <strong>Ticket Management</strong> is activated for the project and <strong>Project Diary</strong> is not, the project opens directly to the Ticket List.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><figure class="shot" style="--w:280px;"><img src="'+r+'" alt="Link to Settings" width="250" loading="lazy"></figure><figure class="shot" style="--w:280px;"><img src="'+c+'" alt="Settings" width="250" loading="lazy"></figure><p>The <strong>Settings</strong> icon opens a page with a few configuration options:</p><ul><li><strong>Signature Settings</strong> → opens the signature settings for the user account.</li><li><strong>Work Offline</strong> → allows the user to switch to offline mode if they do not want to use mobile data. An Internet connection is required to synchronize local data with the server, and the user must manually switch back to online mode here.</li><li><strong>Feedback</strong> → Do you have comments about the app? Do you have an idea for how to improve it? You can submit your comments using the form available through this link.</li><li><strong>What&#39;s New</strong> → opens the information window that was displayed when you entered the app but that you did not have time to read. Important information about new features and changes is displayed when you log in, but you can also access it here at any time.</li><li><strong>Log Out</strong> → if you need to log in with a different account, or simply want to log out before closing the app, you can do so here.</li></ul>',25)])])}const P=h(u,[["render",m]]);export{T as __pageData,P as default};
